#include "FreeRTOS.h"
#include "task.h"

static void tache_regulation(void *arg)
{
    TickType_t prochain = xTaskGetTickCount();
    const TickType_t periode = pdMS_TO_TICKS(1);   /* 1 ms */

    for (;;) {
        lire_capteur();
        calculer_commande();
        vTaskDelayUntil(&prochain, periode);   /* réveil à date absolue */
    }
}

void app_main(void)
{
    xTaskCreate(tache_regulation, "regul", 512, NULL,
                configMAX_PRIORITIES - 1, NULL);
    vTaskStartScheduler();
}

#include <sched.h>
#include <sys/mman.h>
#include <time.h>

#define PERIODE_NS 1000000L               /* 1 ms */

int main(void)
{
    struct sched_param sp = { .sched_priority = 80 };
    struct timespec t;

    mlockall(MCL_CURRENT | MCL_FUTURE);   /* pas de faute de page en route */
    sched_setscheduler(0, SCHED_FIFO, &sp);

    clock_gettime(CLOCK_MONOTONIC, &t);
    for (;;) {
        t.tv_nsec += PERIODE_NS;
        if (t.tv_nsec >= 1000000000L) {
            t.tv_nsec -= 1000000000L;
            t.tv_sec++;
        }
        clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &t, NULL);
        /* travail périodique ici */
    }
}

